/**
 * Catalogue domain types. The mock API in public/api/v1/catalogue (generated by
 * scripts/catalogue/import-catalogue.mjs) and, later, the real backend return these shapes.
 * Money is always in paise (integer, 1/100 rupee).
 */

export type MediaKind = 'mockup' | 'photo' | 'stock';

export interface ProductImage {
  kind: MediaKind;
  /** Media ref (see lib/media.ts) or an absolute URL for external stock images. */
  src: string;
  alt: string;
}

export interface CategorySummary {
  slug: string;
  name: string;
  productCount: number;
  fromPriceCents: number | null;
}

export interface NavItem {
  name: string;
  href: string;
  isNew: boolean;
}

export interface NavGroup {
  id: string;
  name: string;
  items: NavItem[];
}

export interface Category extends CategorySummary {
  id: string;
  description: string;
  sortOrder: number;
  isFeatured: boolean;
  heroImage: ProductImage | null;
  subTypes: { slug: string; name: string }[];
  navGroups: NavGroup[];
}

export interface Collection {
  id: string;
  name: string;
  items: NavItem[];
}

export type PrintCategory = 'flat_print' | 'apparel' | 'wrap';
export type TrimShape = 'rectangle' | 'rounded-rectangle' | 'circle';

export interface PrintConfig {
  category: PrintCategory;
  canvasWidthPx: number;
  canvasHeightPx: number;
  dpi: number;
  bleedPx: number;
  safeZonePx: number;
  trimShape: TrimShape;
  mockups: { front: string | null; back: string | null };
  model3d: { src: string | null; colorMaterialName: string | null; printAreas: unknown[] } | null;
  printAreaSizeMultiplier: number;
}

export interface OptionValue {
  id: string;
  key: string;
  label: string;
  priceDeltaCents: number;
  /** Units in this tier, for "Quantity" groups ("250 cards" → 250). */
  quantity?: number | null;
}

export interface OptionGroup {
  id: string;
  name: string;
  values: OptionValue[];
}

export type StockStatus = 'in_stock' | 'out_of_stock' | 'made_to_order';

export interface Variant {
  id: string;
  sku: string;
  priceCents: number;
  compareAtPriceCents: number | null;
  stockStatus: StockStatus;
  isDefault: boolean;
  /** One value id per option group, sorted. */
  optionValueIds: string[];
}

export interface ProductSummary {
  id: string;
  slug: string;
  name: string;
  categorySlug: string | null;
  shortDescription: string;
  fromPriceCents: number;
  toPriceCents: number;
  isCustomizable: boolean;
  isFeatured: boolean;
  isNew: boolean;
  image: ProductImage | null;
  printCategory: PrintCategory | null;
  optionGroupNames: string[];
}

export interface Product extends Omit<ProductSummary, 'image' | 'optionGroupNames'> {
  description: string;
  basePriceCents: number;
  freeShippingThresholdCents: number | null;
  /** "sets" = the stepper multiplies the chosen quantity tier (original "Batches"). */
  quantityStepper: 'sets' | 'units';
  hasPriceBreaks: boolean;
  dispatchDays: { min: number; max: number } | null;
  images: ProductImage[];
  optionGroups: OptionGroup[];
  variants: Variant[];
  print: PrintConfig | null;
}
